"use strict";

const fs = require("fs");
const path = require("path");

function writeFallback(root) {
  const dir = root || __dirname;
  const bots = JSON.parse(fs.readFileSync(path.join(dir, "data", "bots.json"), "utf8"));
  const events = JSON.parse(fs.readFileSync(path.join(dir, "data", "events.json"), "utf8"));
  const body =
    "/* Generated by node sync-data.js from data/bots.json and data/events.json. Do not edit by hand. */\n" +
    "window.AgentTownFallback = " +
    JSON.stringify({ bots: bots, events: events }) +
    ";\n";
  fs.writeFileSync(path.join(dir, "data", "fallback-data.js"), body);
}

if (require.main === module) {
  writeFallback(__dirname);
  console.log("Wrote data/fallback-data.js");
}

module.exports = { writeFallback };
